def solve(g):
    H=len(g);W=len(g[0]);out=[r[:] for r in g]
    seen=set()
    # find connected components of nonzero colors
    seen=[[False]*W for _ in range(H)]
    from collections import deque
    for i in range(H):
        for j in range(W):
            if g[i][j]!=0 and not seen[i][j]:
                col=g[i][j]; q=deque([(i,j)]); cells=[]
                seen[i][j]=True
                while q:
                    x,y=q.popleft(); cells.append((x,y))
                    for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
                        a,b=x+dx,y+dy
                        if 0<=a<H and 0<=b<W and g[a][b]==col and not seen[a][b]:
                            seen[a][b]=True;q.append((a,b))
                rs=[x for x,_ in cells]; cs=[y for _,y in cells]
                rmin,rmax,cmin,cmax=min(rs),max(rs),min(cs),max(cs)
                h=rmax-rmin+1; w=cmax-cmin+1
                if len(cells)==h*w and h>=3 and w>=3:
                    pat=[[('#' if (r%2==0 or c%2==0) else '.') for c in range(w)] for r in range(h)]
                    for r in range(h):
                        for c in range(w):
                            out[rmin+r][cmin+c]= int('#') if pat[r][c]=='#' else 0
    return out
