def f(g):
    H=len(g);W=len(g[0]);out=[r[:] for r in g]; seen=[[False]*W for _ in range(H)]
    import collections
    for i in range(H):
        for j in range(W):
            if g[i][j]!=0 and not seen[i][j]:
                col=g[i][j]; q=collections.deque([(i,j)]); cells=[]; seen[i][j]=True
                while q:
                    x,y=q.popleft(); cells.append((x,y))
                    for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
                        a,b=x+dx,y+dy
                        if 0<=a<H and 0<=b<W and g[a][b]==col and not seen[a][b]:
                            seen[a][b]=True;q.append((a,b))
                rs=[x for x,_ in cells]; cs=[y for _,y in cells]
                rmin,rmax,cmin,cmax=min(rs),max(rs),min(cs),max(cs)
                h,w=rmax-rmin+1,cmax-cmin+1
                if h>=3 and w>=3 and len(cells)==h*w:
                    keep=True
                    for other_col in set(x for r in g for x in r if x!=0):
                        if other_col==col: continue
                        ocells=[(x,y) for x in range(H) for y in range(W) if g[x][y]==other_col]
                        ors=[x for x,_ in ocells]; occ=[y for _,y in ocells]
                        if not (max(ors)<rmin or min(ors)>rmax or max(occ)<cmin or min(occ)>cmax):
                            keep=False;break
                    erase=(not keep) and (all(r>=rmax for r in [i for i in range(H) for j in range(W) if g[i][j]==col]))
                    if erase:
                        for x in range(rmin,rmax+1):
                            for y in range(cmin,cmax+1): out[x][y]=0
                        continue
                    pat=[[('#' if (r%2==0 or c%2==0) else '.') for c in range(w)] for r in range(h)]
                    for r in range(h):
                        for c in range(w): out[rmin+r][cmin+c]=int(pat[r][c]=='#')
    return out
