def is_diamond(col,g,(rmin,rmax,cmin,cmax),h,w):
    sub=[g[r][cmin:cmax+1] for r in range(rmin,rmax+1)]
    border = [sub[0],sub[-1]]+[row[0] for row in sub]+[row[-1] for row in sub]
    ok=all(x==col for x in border)
    if not ok or h<3 or w<3: return False
    diam=[''.join(str(x) if x else '.' for x in d) for d in [['#','#','.','.','.','.', '#','#']]]
    diamond_sub=[[('#' if (r+c)%2==0 else '.') for c in range(w)] for r in range(h)]
    for r in range(h-2):
        for c in range(w-2):
            if diamond_sub[r+1][c+1]!=str(sub[r+1][c+1]): return False
    # but check equality exactly to the diamond shape including borders
    for r in range(h):
        for c in range(w):
            if sub[r][c]!=diamond_sub[r][c]: return False
    return True
