    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load(); print(sorted(G))
boxes=[]
for k in sorted(G):
    gi=G[k]; go=G.get(k+' output')
    H=len(gi);W=len(gi[0])
    seen=[[False]*W for _ in range(H)]
    for i in range(H):
        for j in range(W):
            if gi[i][j] and not seen[i][j]:
                col=gi[i][j]; stack=[(i,j)]; cells=[]; seen[i][j]=True
                while stack:
                    x,y=stack.pop(); cells.append((x,y))
                    for dx in(-1,0,1):
                        for dy in(-1,0,1):
                            a,b=x+dx,y+dy
                            if 0<=a<H and 0<=b<W and not seen[a][b] and gi[a][b]==col:
                                seen[a][b]=True; stack.append((a,b))
                rs=[x for x,_ in cells]; cs=[y for _,y in cells]
                r0,r1,c0,c1=min(rs),max(rs),min(cs),max(cs)
                h=r1-r0+1;w=c1-c0+1
                n=(h+1)*(w+1)-1
                complete=len(cells)==n
                if go is None: continue
                filled=any(go[x][y]==col for x in range(r0+1,r1) for y in range(c0+1,c1)))
                boxes.append(dict(k=k,color=col,h=h,w=w,r0=r0,c0=c0,n=n,complete=complete,
                                  filled=filled))
for B in sorted(boxes,key=lambda b:(b['k'],b['color'])):
    print(B['k'],B['color'],B['h'],B['w'],'filled' if B['filled'] else 'empty-interior',B['complete'])

