                while stack:
                    x,y=stack.pop(); cells.append((x,y))
                    for dx in(-1,0,1):
                        for dy in(-1,0,1):
                            a,b=x+dx,y+dy
                            if 0<=a<H and 0<=b<W and not seen[a][b] and gi[a][b]==col:
                                seen[a][b]=True; stack.append((a,b))
                rs=[x for x,_ in cells]; cs=[y for _,y in cells]
                r0,r1,c0,c1=min(rs),max(rs),min(cs),max(cs)
                h=r1-r0+1; w=c1-c0+1
                n=(h+1)*(w+1)-1
