import collections
def rings(g):
    Hh,Ww=len(g),len(g[0])
    seen=[[False]*Ww for _ in range(Hh)]
    Rs=[]
    for i in range(Hh):
        for j in range(Ww):
            if g[i][j]!=0 and not seen[i][j]:
                stack=[(i,j)]; seen[i][j]=True; comp=[]
                while stack:
                    a,b=stack.pop(); comp.append((a,b))
                    for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
                        x,y=a+da,b+db
                        if 0<=x<Hh and 0<=y<Ww and g[x][y]==g[i][j] and not seen[x][y]:
                            seen[x][y]=True; stack.append((x,y))
                rs=rings_of_manual(g,comp)
                if rs: Rs.extend(rs)
    return Rs
