    per=len(cells); expected=2*(h+w)-4
    if per!=expected or r1-r0+1==1 or c1-c0+1==1: return []
    return {'col':g[r0][c0],'r0':r0,'c0':c0,'h':h,'w':w,'intern':(h-2,w-2)}
