def comps(g):
    H,W=len(g),len(g[0]); seen=set(); out=[]
    for a in range(H):
        for b in range(W):
            if g[a][b] and (a,b) not in seen:
                col=g[a][b]; st=[(a,b)]; comp=set()
                while st:
                    x,y=st.pop()
                    if (x,y) in comp or g[x][y]!=col: continue
                    comp.add((x,y))
                    for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
                        nx,ny=x+dx,y+dy
                        if 0<=nx<H and 0<=ny<W and g[nx][ny]==col and (nx,ny) not in comp: st.append((nx,ny))
                seen|=comp; out.append(comp)
    return out

def solve(g):
    H=len(g); W=len(g[0])
    seen=[[False]*W for _ in range(H)]
    rings=[]
    for r in range(H):
        for c in range(W):
            if g[r][c]!=0 and not seen[r][c]:
                # ring must be border of bbox; check the enclosing rectangle
                col=g[r][c]
                # find its ring extent: scan right/down while same color on top row/left col? use simple: flood of 4-conn comp but only cells where cell belongs to a border row/col
                st=[(r,c)]; comp=set()
                while st:
                    x,y=st.pop()
                    if (x,y) in comp: continue
                    comp.add((x,y))
                    st+= [(x+1,y),(x-1,y),(x,y+1),(x,y-1)]
                rs=min(a for a,b in comp); cmin=min(b for a,b in comp)
                h=max(a for a,b in comp)-rs+1; ww=max(b for a,b in comp)-cmin+1
                ok=all(g[a][b]==col for a in (rs,rs+h-1) for b in range(cmin,cmin+ww)) and \
                    all(g[a][b]==col for b in (cmin,cmin+ww-1) for a in range(rs,rs+h))
                if ok and len(comp)==2*h+2*ww-4:
                    for a,b in comp: seen[a][b]=True
                    rings.append((h,ww,col,rs,cmin,[(a-rs-1,b-cmin-1) for a in range(1,h-1) for b in range(1,ww-1)]))
    groups={}
    for r in rings: groups.setdefault((r[0],r[1]),[]).append(r)
    o=[row[:] for row in g]
    for (hh,ww),rl in groups.items():
        if len(rl)<2:
            for h,w,col,rs,cmin,inn in rl:
                for a,b in inn: o[a][b]=0
        else:
            mset=set()
            for h,w,col,rs,cmin,inn in rl:
                for a,b in inn:
                    if g[a][b]!=0: mset.add((a-rs,b-cmin))
            pat={(i,j) for i,j in mset}
            for h,w,col,rs,cmin,inn in rl:
                for a,b in inn:
                    o[a][b]= col if (a-rs,b-cmin) in pat else 0
    return o
for k in ['Demo pair 1','Demo pair 2','Demo pair 3']:
    print(k,'ok' if solve(G[k+' input'])==G[k+' output'] else 'MISMATCH')

